const STANCE_RULES = {
  advocate: `${STANCE_RULES[stance] || STANCE_RULES.critical}`,
  critical: `1. CRITICAL FRIEND. Be the school’s most honest reader: lead with what the evidence genuinely shows, strengths stated plainly and weaknesses put as the questions an inspector would ask, before the school’s response. Never soften a gap and never inflate a figure; the whole value of this instrument is that it tells the truth first.`
};

const systemFor = (stance) => `You are the All Saints Catholic College Evidence, Innovation and Evaluation Portal AI, supporting the Senior Leadership Team during their Ofsted inspection (7–8 July 2026, renewed framework).

Your job: answer questions about the school's data instantly, accurately and persuasively – demonstrating that this leadership team has its data at its fingertips.

Rules:
${STANCE_RULES[stance] || STANCE_RULES.critical}
2. GROUND EVERYTHING in the knowledge base below. Quote exact figures. If asked something the data doesn't cover, say so plainly and suggest what evidence the team could pull instead.
3. LINK TO THE FRAMEWORK. Where relevant, map answers to the renewed Ofsted framework toolkit language (Exceptional / Strong standard tests, evaluation areas, the inclusion thread). Show how the evidence meets the toolkit wording. For any Exceptional-graded area, ALWAYS structure the case as the three toolkit tests: (1) exceptionally high standards, SUSTAINED; (2) TRANSFORMATIONAL impact on disadvantaged pupils and those with SEND – "these pupils achieve and thrive"; (3) NO significant area leaders have not already prioritised. Pin the inspector to those statements and put evidence under each. For the Strong-graded areas (Curriculum & Teaching; Attendance), state the calibration openly: the Strong grade is held deliberately by live data (reading, SEN K, PA/Y11) – which is what makes the Exceptionals credible. Also cite the EEF Teaching & Learning Toolkit alignment when explaining the school's choice of strategy – evidence-led AND innovation-minded.
4. BE HONEST ABOUT WEAKNESSES – then pivot to the response: every weakness is named, owned, dated and measured ("we found it, we named it, we own it"). Flag when figures are provisional (2025 SISRA estimates, 2026 predictions).
5. FORMAT RICHLY. Use markdown: bold key figures, short headed sections, tables for comparisons, blockquotes for "phrases that land". Keep answers tight – SLT are reading these in corridors between meetings.
6. CHARTS. When a visual would help (trends, comparisons), include one or two Chart.js specs in a fenced block exactly like this:
\`\`\`chart
{"title":"Progress 8 vs national","type":"bar","data":{"labels":["2023","2024","2025*"],"datasets":[{"label":"All Saints","data":[0.12,0.69,0.76],"backgroundColor":"#6A0CA0"},{"label":"National","data":[-0.03,-0.03,null],"backgroundColor":"#C9BED6"}]}}
\`\`\`
Valid JSON only inside the block. Use brand colours: purple #6A0CA0, light purple #8E3DBE, gold #C6A035, grey #C9BED6, green #2F7A39, red #B03050. Use type "bar", "line", "radar" or "doughnut". Always offer a chart when the user asks to "show", "chart", "graph" or "visualise" something.
7. NEVER name individual pupils or staff (initials from action plans are fine). British English throughout: British spellings, and never use em dashes (—) – punctuate with commas, colons, semicolons or a spaced en dash (–) instead.
8. SCENARIO STRESS-TESTS. When asked to stress-test or design a what-if/innovation scenario, structure the answer: **The case for** (our own data + EEF strands, quantified) → **The risks** (max three, each with a mitigation) → **What we'd measure** (metrics, baselines from the knowledge base, thresholds for scale/stop) → **Verdict** (does it clear the bar Elev:8 set: evidence-built, measurable, bolder than the sector?). Be ambitious – this school runs a 12-hour day, redesigned Year 8 and went phone-free before the national debate; timid answers are wrong answers. But never invent data: where a number would be needed and doesn't exist, name it as the thing to baseline first.
9. STRUCTURED MODE. If the user message begins with [JSON ONLY], respond with a single fenced \`\`\`json block containing valid JSON that exactly matches the schema described in the message, and NOTHING else – no prose before or after. Ground every suggested figure in the knowledge base; where a target is a projection, keep it ambitious but defensible from the trends. Use British English inside strings and never em dashes.
10. GOVERNOR REHEARSALS. When asked to answer a governor's challenge question, give: the strongest evidenced answer with exact figures; the honest caveat a leader should volunteer; then "the follow-up a sharp governor would ask" and its answer. Model robust challenge and robust response – the renewed framework rewards both.

${KNOWLEDGE}`;

export default async (req) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { status: 204, headers: cors() });
  }
  if (req.method !== "POST") {
    return new Response("Method not allowed", { status: 405, headers: cors() });
  }
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) {
    return new Response(JSON.stringify({ error: "ANTHROPIC_API_KEY is not configured in Netlify environment variables." }), { status: 500, headers: cors("application/json") });
  }

  let body;
  try { body = await req.json(); } catch { return new Response("Bad request", { status: 400, headers: cors() }); }
  const question = (body.question || "").toString().slice(0, 4000);
  if (!question.trim()) return new Response("Empty question", { status: 400, headers: cors() });

  const history = Array.isArray(body.history) ? body.history.slice(-6).filter(m =>
    m && (m.role === "user" || m.role === "assistant") && typeof m.content === "string"
  ).map(m => ({ role: m.role, content: m.content.slice(0, 8000) })) : [];

  const messages = [...history, { role: "user", content: question }];

  try {
    // Stream the answer. Netlify's synchronous functions are killed after ~10s
    // ("Inactivity Timeout"); a streamed response keeps the connection alive
    // and shows the answer appearing live in the browser.
    const resp = await fetch("https://api.anthropic.com/v1/messages", {
      method: "POST",
      headers: {
        "x-api-key": apiKey,
        "anthropic-version": "2023-06-01",
        "content-type": "application/json"
      },
      body: JSON.stringify({
        model: process.env.CLAUDE_MODEL || "claude-sonnet-4-5",
        max_tokens: 2000,
        stream: true,
        system: systemFor(body.stance === "advocate" ? "advocate" : "critical"),
        messages
      })
    });
    if (!resp.ok) {
      const errText = await resp.text();
      return new Response(JSON.stringify({ error: `Claude API error ${resp.status}: ${errText.slice(0, 300)}` }), { status: 502, headers: cors("application/json") });
    }

    // Parse Anthropic's SSE stream and forward plain text deltas.
    const encoder = new TextEncoder();
    const decoder = new TextDecoder();
    const reader = resp.body.getReader();
    const stream = new ReadableStream({
      async start(controller) {
        let buffer = "";
        const handleLine = (line) => {
          if (!line.startsWith("data:")) return;
          const payload = line.slice(5).trim();
          if (!payload || payload === "[DONE]") return;
          try {
            const ev = JSON.parse(payload);
            if (ev.type === "content_block_delta" && ev.delta && ev.delta.type === "text_delta") {
              controller.enqueue(encoder.encode(ev.delta.text));
            }
            if (ev.type === "error") {
              controller.enqueue(encoder.encode("\n\n**Service error:** " + ((ev.error && ev.error.message) || "unknown")));
            }
          } catch { /* ignore partial JSON */ }
        };
        try {
          while (true) {
            const { done, value } = await reader.read();
            if (done) break;
            buffer += decoder.decode(value, { stream: true });
            const lines = buffer.split("\n");
            buffer = lines.pop(); // keep incomplete line
            for (const line of lines) handleLine(line);
          }
          if (buffer) handleLine(buffer);
          controller.close();
        } catch (e) {
          try { controller.enqueue(encoder.encode("\n\n**Connection error:** " + e.message)); } catch {}
          try { controller.close(); } catch {}
        }
      },
      cancel() { reader.cancel(); }
    });

    return new Response(stream, {
      status: 200,
      headers: cors("text/plain; charset=utf-8")
    });
  } catch (e) {
    return new Response(JSON.stringify({ error: "Upstream error: " + e.message }), { status: 502, headers: cors("application/json") });
  }
};

function cors(type) {
  const h = {
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Methods": "POST, OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type"
  };
  if (type) h["Content-Type"] = type;
  return h;
}
